import { Button, Alert, AlertTitle, AlertDescription } from '@newwork/nw-design-system'
import { Spinner } from '@newwork/nw-design-system'
import { PageLayout } from '@newwork/nw-design-system'
import {
  HandshakeIcon,
  ChartBar,
  UsersThree,
  Buildings,
  Users,
  CurrencyDollar,
  List,
  Megaphone,
  House
} from '@phosphor-icons/react'
import { BusinessAppContextProps } from '@/common/BusinessAppContext'
import { LeadList } from './views/lead-view'
import { AccountList } from './views/account-view'
import { ContactList } from './views/contact-view'
import { OpportunityView } from './views/opportunity-view'
import { DashboardView } from './views/dashboard-view'
import { AnalyticsView } from './views/analytics-view'
import { useSalesDashboard } from './views/dashboard-view/hooks/useSalesDashboard'
import { DateRange } from './views/dashboard-view/types/dashboardTypes'
import CampaignManagement from './views/campaign-view/CampaignManagement'
import { TaskView } from './views/task-view'
import { MODULE_COLORS } from '@/common/constants/ui'

export interface CustomerRelationsProps extends BusinessAppContextProps {}

const moduleColor = MODULE_COLORS.CRM
export const CustomerRelations: React.FC<CustomerRelationsProps> = context => {
  const viewOptions = [
    {
      key: 'dashboard',
      icon: <House />,
      label: 'Dashboard'
    },
    {
      key: 'tasks',
      icon: <List />,
      label: 'Tasks'
    },
    {
      key: 'leads',
      icon: <UsersThree />,
      label: 'Leads'
    },
    {
      key: 'accounts',
      icon: <Buildings />,
      label: 'Accounts'
    },
    {
      key: 'contacts',
      icon: <Users />,
      label: 'Contacts'
    },
    {
      key: 'opportunities',
      icon: <CurrencyDollar />,
      label: 'Opportunities'
    },
    {
      key: 'campaigns',
      icon: <Megaphone />,
      label: 'Campaigns'
    },
    {
      key: 'analytics',
      icon: <ChartBar />,
      label: 'Analytics'
    }
  ]

  // Get initial view from URL or default to first view
  const getInitialView = () => {
    const urlParams = new URLSearchParams(window.location.search)
    const viewFromUrl = urlParams.get('view')

    // Validate that the view exists in our options
    if (viewFromUrl && viewOptions.some(option => option.key === viewFromUrl)) {
      return viewFromUrl
    }

    // Default to first view
    return viewOptions[0].key
  }

  const [activeTab, setActiveTab] = useState<string>(getInitialView())
  // Sub-view is now handled inside OpportunityView
  const [dateRange] = useState<DateRange>({
    startDate: new Date(new Date().getFullYear() - 2, 0, 1),
    endDate: new Date()
  })
  const { pipelines, isLoading, error, refetch } = useSalesDashboard(context, dateRange)

  // Update URL when view changes
  const updateUrl = (view: string, subView?: string) => {
    const urlParams = new URLSearchParams(window.location.search)

    // Always set the view parameter (including for default)
    urlParams.set('view', view)

    // Handle subView parameter for opportunities
    if (view === 'opportunities' && subView) {
      // Map internal tab values to URL subView values
      if (subView === 'board') {
        urlParams.set('subView', 'pipeline')
      } else if (subView === 'list') {
        urlParams.set('subView', 'list')
      }
    } else {
      // Clear subView parameter when not in opportunities view
      if (urlParams.has('subView')) {
        urlParams.delete('subView')
      }
    }

    // Clear leadStatus parameter when switching away from leads view
    if (view !== 'leads' && urlParams.has('leadStatus')) {
      urlParams.delete('leadStatus')
    }

    // Clear campaign-specific parameters when switching away from campaigns view
    if (
      view !== 'campaigns' &&
      (urlParams.has('campaignId') || urlParams.has('mainTab') || urlParams.has('recordTab'))
    ) {
      urlParams.delete('campaignId')
      urlParams.delete('mainTab')
      urlParams.delete('recordTab')
    }

    const newUrl = `${window.location.pathname}?${urlParams.toString()}`
    window.history.replaceState({}, '', newUrl)
  }

  const handleTabChange = (key: string) => {
    // Allow all valid tab changes including clicking the same tab to ensure proper highlighting
    if (!key) {
      return
    }
    setActiveTab(key)

    updateUrl(key)
  }

  // Ensure URL always has view parameter on initial load
  useEffect(() => {
    const urlParams = new URLSearchParams(window.location.search)
    if (!urlParams.has('view')) {
      updateUrl(activeTab)
    }
  }, [])

  // Listen for browser back/forward navigation
  useEffect(() => {
    const handlePopState = () => {
      const newView = getInitialView()
      setActiveTab(newView)
    }

    window.addEventListener('popstate', handlePopState)
    return () => window.removeEventListener('popstate', handlePopState)
  }, [])

  const renderDashboardContent = () => {
    if (isLoading) {
      return (
        <div className="gba:flex gba:items-center gba:justify-center gba:py-16">
          <div className="gba:text-center">
            <Spinner size="lg" />
            <div className="gba:mt-4 gba:text-gray-600 gba:text-lg">Loading Customer Relations Dashboard...</div>
          </div>
        </div>
      )
    }

    if (error) {
      return (
        <div className="gba:p-6">
          <Alert variant="destructive" className="gba:shadow-sm">
            <AlertTitle>Error Loading Dashboard</AlertTitle>
            <AlertDescription>{error}</AlertDescription>
            <Button size="sm" onClick={refetch} variant="default">
              Retry
            </Button>
          </Alert>
        </div>
      )
    }

    return <DashboardView pipelines={pipelines} dateRange={dateRange} moduleColor={moduleColor} {...context} />
  }

  const renderAnalyticsContent = () => {
    return (
      <div data-testid="analytics-tab-content">
        <AnalyticsView moduleColor={moduleColor} {...context} />
      </div>
    )
  }

  const renderOpportunitiesContent = () => {
    return <OpportunityView {...context} />
  }

  const renderTabContent = () => {
    switch (activeTab) {
      case 'dashboard':
        return renderDashboardContent()
      case 'tasks':
        return (
          <div data-testid="tasks-tab-content">
            <TaskView {...context} />
          </div>
        )
      case 'leads':
        return (
          <div data-testid="leads-tab-content">
            <LeadList {...context} sourceApp="CRM" />
          </div>
        )
      case 'accounts':
        return (
          <div data-testid="accounts-tab-content">
            <AccountList {...context} sourceApp="CRM" />
          </div>
        )
      case 'contacts':
        return (
          <div data-testid="contacts-tab-content">
            <ContactList {...context} sourceApp="CRM" />
          </div>
        )
      case 'campaigns':
        return (
          <div data-testid="campaigns-tab-content">
            <CampaignManagement {...context} />
          </div>
        )
      case 'opportunities':
        return renderOpportunitiesContent()
      case 'analytics':
        return renderAnalyticsContent()
      default:
        return null
    }
  }

  return (
    <div data-testid="customer-relations-app">
      <PageLayout
        headerIcon={HandshakeIcon}
        headerTitle="Customer Relations"
        headerDescription="Manage customer relationships, track leads, accounts, contacts, and sales opportunities"
        headerSubViews={{
          value: activeTab,
          onValueChange: handleTabChange,
          items: viewOptions.map(option => ({
            value: option.key,
            label: option.label,
            icon: option.icon
          }))
        }}
        variant={moduleColor}
        className="gba:min-h-screen"
      >
        <div className="gba:h-full gba:overflow-auto">{renderTabContent()}</div>
      </PageLayout>
    </div>
  )
}

export default CustomerRelations","numLines":276,"startLine":1,"totalLines":276}}

{"type":"text","file":{"filePath":"/tmp/every-agent-YFP3nb/repo/src/business-apps/crm/customers/apps/customer-relations/views/opportunity-view/OpportunityView.tsx","content":"import React, { useEffect, useState, useCallback } from 'react'
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@newwork/nw-design-system'
import { BusinessAppContextProps } from '@/common/BusinessAppContext'
import { OpportunityList } from './opportunity-list'
import { OpportunityBoard } from './opportunity-board'
import { OpportunityStatisticsWithTrend } from './opportunity-list/components/OpportunityStatistics'
import { useOpportunityStatisticsWithTrend } from './opportunity-list/hooks/useOpportunityStatisticsWithTrend'

export interface OpportunityViewProps extends BusinessAppContextProps {}

// Map URL subView values to internal tab values and vice versa
const mapUrlToTab = (subView: string | null): 'list' | 'board' => {
  if (subView === 'pipeline') return 'board'
  return 'list'
}

const mapTabToUrl = (tab: 'list' | 'board'): 'list' | 'pipeline' => {
  return tab === 'board' ? 'pipeline' : 'list'
}

export const OpportunityView: React.FC<OpportunityViewProps> = context => {
  const getInitialSubTab = useCallback((): 'list' | 'board' => {
    const urlParams = new URLSearchParams(window.location.search)
    return mapUrlToTab(urlParams.get('subView'))
  }, [])

  const [activeSubTab, setActiveSubTab] = useState<'list' | 'board'>(getInitialSubTab())

  const updateSubViewInUrl = useCallback((tab: 'list' | 'board') => {
    const urlParams = new URLSearchParams(window.location.search)
    urlParams.set('subView', mapTabToUrl(tab))
    const newUrl = `${window.location.pathname}?${urlParams.toString()}`
    window.history.replaceState({}, '', newUrl)
  }, [])

  useEffect(() => {
    // Ensure subView param is present on mount using current tab
    const urlParams = new URLSearchParams(window.location.search)
    if (!urlParams.has('subView')) {
      updateSubViewInUrl(getInitialSubTab())
    }
  }, [getInitialSubTab, updateSubViewInUrl])

  // Listen for browser navigation to keep tab in sync
  useEffect(() => {
    const handlePopState = () => {
      setActiveSubTab(getInitialSubTab())
    }
    window.addEventListener('popstate', handlePopState)
    return () => window.removeEventListener('popstate', handlePopState)
  }, [getInitialSubTab])

  const handleSubTabChange = (value: string) => {
    const tab = (value === 'board' ? 'board' : 'list') as 'list' | 'board'
    setActiveSubTab(tab)
    updateSubViewInUrl(tab)
  }

  // Load statistics once at view level (shared across tabs)
  const opportunityStatistics = useOpportunityStatisticsWithTrend({ ...context, sourceApp: 'CRM' })
  const handleRetryStatistics = useCallback(() => {
    opportunityStatistics.refetch()
  }, [opportunityStatistics])

  return (
    <div data-testid="customer-opportunities-view">
      {/* Statistics above tabs */}
      <div data-testid="customer-opportunity-statistics" className="gba:mb-6">
        {opportunityStatistics.trendData ? (
          <OpportunityStatisticsWithTrend
            trendData={opportunityStatistics.trendData}
            isLoading={opportunityStatistics.isLoading}
            error={opportunityStatistics.error}
            onRetry={handleRetryStatistics}
          />
        ) : (
          <div>Loading statistics...</div>
        )}
      </div>

      <Tabs value={activeSubTab} onValueChange={handleSubTabChange}>
        <TabsList className="gba:mb-4">
          <TabsTrigger value="list" data-testid="opportunities-list-tab">
            List View
          </TabsTrigger>
          <TabsTrigger value="board" data-testid="opportunities-board-tab">
            Board View
          </TabsTrigger>
        </TabsList>
        <TabsContent value="list">
          <OpportunityList {...context} sourceApp="CRM" />
        </TabsContent>
        <TabsContent value="board">
          <OpportunityBoard {...context} sourceApp="CRM" />
        </TabsContent>
      </Tabs>
    </div>
  )
}

