{"type":"text","file":{"filePath":"/tmp/every-agent-YFP3nb/repo/src/components/kanban-board/KanbanBoard.tsx","content":"import React, { useState } from 'react'
import {
  DndContext,
  DragOverlay,
  useSensors,
  useSensor,
  PointerSensor,
  closestCorners,
  DragEndEvent,
  DragOverEvent
} from '@dnd-kit/core'
import { Spinner } from '@newwork/nw-design-system'
import { KanbanColumn } from './components/KanbanColumn'
import { KanbanCard } from './components/KanbanCard'
import { KanbanItem, KanbanBoardProps } from './types'

export const KanbanBoard: React.FC<KanbanBoardProps> = ({
  stages,
  items,
  onDragEnd,
  renderCard,
  renderStageHeader,

  // Generic props
  className = '',
  loading = false,
  emptyStateMessage,
  allowReorderWithinStage = true,
  ...props
}) => {
  const [activeItem, setActiveItem] = useState<KanbanItem | null>(null)
  const [sourceStage, setSourceStage] = useState<string | null>(null)
  const [dragOverStage, setDragOverStage] = useState<string | null>(null)
  const [dragOverItem, setDragOverItem] = useState<string | null>(null)
  const [insertPosition, setInsertPosition] = useState<'before' | 'after' | null>(null)

  const sensors = useSensors(
    useSensor(PointerSensor, {
      activationConstraint: {
        distance: 8
      }
    })
  )

  const handleDragStart = (event: any) => {
    const { active } = event
    const itemId = active.id

    const draggedItem = items.find(item => item.id === itemId)

    setActiveItem(draggedItem || null)
    setSourceStage(draggedItem?.stageId || null)
  }

  const handleDragOver = (event: DragOverEvent) => {
    const { over, active } = event

    if (over) {
      const overId = over.id as string
      const activeId = active.id as string

      // Find the active item
      const activeItem = items.find(item => item.id === activeId)

      // Check if we're hovering over a stage (column)
      const stage = stages.find(s => s.id === overId)
      if (stage) {
        // Only show feedback if this is not the source stage
        if (stage.id !== sourceStage) {
          setDragOverStage(overId)
        } else {
          setDragOverStage(null)
        }
        setDragOverItem(null)
        setInsertPosition(null)
      } else {
        // We're hovering over another item
        const overItem = items.find(item => item.id === overId)
        if (overItem && activeItem) {
          const overStageId = overItem.stageId
          const activeStageId = activeItem.stageId

          // Only show feedback if this is not the source stage
          if (overStageId !== sourceStage) {
            setDragOverStage(overStageId || null)
            // No insertion lines - we'll show "Drop here" card at first position instead
            setDragOverItem(null)
            setInsertPosition(null)
          } else {
            // In source stage - no visual feedback
            setDragOverStage(null)
            setDragOverItem(null)
            setInsertPosition(null)
          }
        } else {
          setDragOverStage(null)
          setDragOverItem(null)
          setInsertPosition(null)
        }
      }
    } else {
      setDragOverStage(null)
      setDragOverItem(null)
      setInsertPosition(null)
    }
  }

  const handleDragEnd = (event: DragEndEvent) => {
    const { active, over } = event

    // Clear all drag over states
    setDragOverStage(null)
    setDragOverItem(null)
    setInsertPosition(null)
    setActiveItem(null)
    setSourceStage(null)

    if (!over || active.id === over.id) {
      return
    }

    const activeId = active.id as string
    const overId = over.id as string

    const activeItem = items.find(item => item.id === activeId)
    if (!activeItem) return

    // Check if we're dropping on a stage (inter-column move to end)
    const targetStage = stages.find(s => s.id === overId)
    if (targetStage) {
      // Moving to a different stage at the end
      const activeStageId = activeItem.stageId
      if (activeStageId !== targetStage.id) {
        onDragEnd?.(activeId, targetStage.id, items.length)
      }
      return
    }

    // Check if we're dropping on another item
    const overItem = items.find(item => item.id === overId)
    if (overItem) {
      const activeStageId = activeItem.stageId
      const overStageId = overItem.stageId

      if (activeStageId === overStageId) {
        if (!allowReorderWithinStage) {
          // Reordering disabled: treat as no-op
          return
        }
        // Reordering within the same column - calculate new position
        const stageItems = items.filter(item => item.stageId === activeStageId)
        const activeIndex = stageItems.findIndex(item => item.id === activeId)
        const overIndex = stageItems.findIndex(item => item.id === overId)

        if (activeIndex !== overIndex) {
          onDragEnd?.(activeId, activeStageId || '', overIndex)
        }
      } else {
        // Moving to a different stage with specific positioning
        const targetStageItems = items.filter(item => item.stageId === overStageId)
        const insertIndex = targetStageItems.findIndex(item => item.id === overId)

        // Insert after the target item
        const newPosition = insertIndex + 1

        onDragEnd?.(activeId, overStageId || '', newPosition)
      }
    }
  }

  if (loading) {
    return (
      <div className="gba:flex gba:items-center gba:justify-center gba:w-full gba:h-full gba:p-8">
        <div className="gba:text-center">
          <Spinner size="lg" />
          <p className="gba:mt-4 gba:text-gray-500">Loading...</p>
        </div>
      </div>
    )
  }

  if (stages.length === 0) {
    return (
      <div className="gba:flex gba:items-center gba:justify-center gba:w-full gba:h-full gba:p-8">
        <div className="gba:text-center gba:text-gray-500">No stages available</div>
      </div>
    )
  }

  return (
    <div className={className} {...props}>
      <DndContext
        sensors={sensors}
        collisionDetection={closestCorners}
        onDragStart={handleDragStart}
        onDragOver={handleDragOver}
        onDragEnd={handleDragEnd}
      >
        <div className="gba:flex gba:flex-1 gba:overflow-x-auto gba:overflow-y-hidden gba:scroll-smooth gba:p-4 gba:gap-4">
          {stages.map(stage => (
            <KanbanColumn
              key={stage.id}
              stage={stage}
              items={items
                .filter(item => item.stageId === stage.id)
                .sort((a, b) => (a.position || 0) - (b.position || 0))}
              renderCard={renderCard}
              renderStageHeader={renderStageHeader}
              isDraggedOver={dragOverStage === stage.id}
              isDragging={activeItem !== null}
              dragOverItem={dragOverItem}
              insertPosition={insertPosition}
              sourceStageId={sourceStage}
            />
          ))}
        </div>

        <DragOverlay>
          {activeItem && renderCard ? renderCard(activeItem) : activeItem ? <KanbanCard item={activeItem} /> : null}
        </DragOverlay>
      </DndContext>
    </div>
  )
}","numLines":224,"startLine":1,"totalLines":224}}

{"type":"text","file":{"filePath":"/tmp/every-agent-YFP3nb/repo/src/business-apps/crm/customers/apps/customer-relations/views/opportunity-view/OpportunityView.tsx","content":"import React, { useEffect, useState, useCallback } from 'react'
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@newwork/nw-design-system'
import { BusinessAppContextProps } from '@/common/BusinessAppContext'
import { OpportunityList } from './opportunity-list'
import { OpportunityBoard } from './opportunity-board'
import { OpportunityStatisticsWithTrend } from './opportunity-list/components/OpportunityStatistics'
import { useOpportunityStatisticsWithTrend } from './opportunity-list/hooks/useOpportunityStatisticsWithTrend'

export interface OpportunityViewProps extends BusinessAppContextProps {}

// Map URL subView values to internal tab values and vice versa
const mapUrlToTab = (subView: string | null): 'list' | 'board' => {
  if (subView === 'pipeline') return 'board'
  return 'list'
}

const mapTabToUrl = (tab: 'list' | 'board'): 'list' | 'pipeline' => {
  return tab === 'board' ? 'pipeline' : 'list'
}

export const OpportunityView: React.FC<OpportunityViewProps> = context => {
  const getInitialSubTab = useCallback((): 'list' | 'board' => {
    const urlParams = new URLSearchParams(window.location.search)
    return mapUrlToTab(urlParams.get('subView'))
  }, [])

  const [activeSubTab, setActiveSubTab] = useState<'list' | 'board'>(getInitialSubTab())

  const updateSubViewInUrl = useCallback((tab: 'list' | 'board') => {
    const urlParams = new URLSearchParams(window.location.search)
    urlParams.set('subView', mapTabToUrl(tab))
    const newUrl = `${window.location.pathname}?${urlParams.toString()}`
    window.history.replaceState({}, '', newUrl)
  }, [])

  useEffect(() => {
    // Ensure subView param is present on mount using current tab
    const urlParams = new URLSearchParams(window.location.search)
    if (!urlParams.has('subView')) {
      updateSubViewInUrl(getInitialSubTab())
    }
  }, [getInitialSubTab, updateSubViewInUrl])

  // Listen for browser navigation to keep tab in sync
  useEffect(() => {
    const handlePopState = () => {
      setActiveSubTab(getInitialSubTab())
    }
    window.addEventListener('popstate', handlePopState)
    return () => window.removeEventListener('popstate', handlePopState)
  }, [getInitialSubTab])

  const handleSubTabChange = (value: string) => {
    const tab = (value === 'board' ? 'board' : 'list') as 'list' | 'board'
    setActiveSubTab(tab)
    updateSubViewInUrl(tab)
  }

  // Load statistics once at view level (shared across tabs)
  const opportunityStatistics = useOpportunityStatisticsWithTrend({ ...context, sourceApp: 'CRM' })
  const handleRetryStatistics = useCallback(() => {
    opportunityStatistics.refetch()
  }, [opportunityStatistics])

  return (
    <div data-testid="customer-opportunities-view">
      {/* Statistics above tabs */}
      <div data-testid="customer-opportunity-statistics" className="gba:mb-6">
        {opportunityStatistics.trendData ? (
          <OpportunityStatisticsWithTrend
            trendData={opportunityStatistics.trendData}
            isLoading={opportunityStatistics.isLoading}
            error={opportunityStatistics.error}
            onRetry={handleRetryStatistics}
          />
        ) : (
          <div>Loading statistics...</div>
        )}
      </div>

      <Tabs value={activeSubTab} onValueChange={handleSubTabChange}>
        <TabsList className="gba:mb-4">
          <TabsTrigger value="list" data-testid="opportunities-list-tab">
            List View
          </TabsTrigger>
          <TabsTrigger value="board" data-testid="opportunities-board-tab">
            Board View
          </TabsTrigger>
        </TabsList>
        <TabsContent value="list">
          <OpportunityList {...context} sourceApp="CRM" />
        </TabsContent>
        <TabsContent value="board">
          <OpportunityBoard {...context} sourceApp="CRM" />
        </TabsContent>
      </Tabs>
    </div>
  )
}

export default OpportunityView","numLines":101,"startLine":1,"totalLines":101}}

{"type":"text","file":{"filePath":"/tmp/every-agent-YFP3nb/repo/src/business-apps/crm/customers/apps/customer-relations/views/opportunity-view/opportunity-board/OpportunityBoard.tsx","content":"import { useState, useEffect } from 'react'
import {
  DndContext,
  DragOverlay,
  useSensors,
  useSensor,
  PointerSensor,
  closestCorners,
  DragOverEvent,
  DragEndEvent
} from '@dnd-kit/core'
import { arrayMove } from '@dnd-kit/sortable'
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
  RadioGroup,
  RadioGroupItem,
  Label
} from '@newwork/nw-design-system'
import { useKanbanStore } from './lib/kanban-store'
import { KanbanColumn, OpportunityCard, OpportunityDialog, EmployeeSelector } from './components'
import OpportunityRecord from '@/business-apps/crm/common/apps/opportunity-record/OpportunityRecord'
// import { getTranslationFromI18nKeyAndLabel } from "@/common/utils/windowUtils";
import { useSalesPipelines } from './hooks/useSalesPipelines'
import { usePipelineStages } from './hooks/usePipelineStages'
import { FIXED_STAGES } from './lib/stages'
import type { Opportunity } from './lib/types'

interface BusinessAppContextProps {
  accessToken: string
  userInfo?: any
  employeeId?: string
  structureId?: string
}

interface OpportunityBoardProps extends BusinessAppContextProps {
  sourceApp?: string
}

export function OpportunityBoard({ accessToken, userInfo, sourceApp }: OpportunityBoardProps) {
  const employeeId = userInfo?.employeeDetails?.employeeId
  const {
    stages,
    opportunities,
    // moveOpportunity,
    moveOpportunityToStage,
    moveOpportunityToPosition,
    reorderOpportunities,
    fetchOpportunities,
    updateStages,
    selectOpportunity,
    selectedOpportunity,
    isViewingOpportunity
  } = useKanbanStore()

  const [activeOpportunity, setActiveOpportunity] = useState<Opportunity | null>(null)
  const [filterMode, setFilterMode] = useState<'my' | 'all' | 'selected'>('my')
  const [selectedEmployeeIds, setSelectedEmployeeIds] = useState<string[]>([])
  const [selectedPipelineId, setSelectedPipelineId] = useState<string | undefined>(undefined)
  const [dragOverStage, setDragOverStage] = useState<string | null>(null)
  const [dragOverOpportunity, setDragOverOpportunity] = useState<string | null>(null)
  const [insertPosition, setInsertPosition] = useState<'before' | 'after' | null>(null)

  // Fetch sales pipelines
  const { pipelines, isLoading: pipelinesLoading } = useSalesPipelines(accessToken)

  // Set default pipeline to "standard" when pipelines are loaded
  useEffect(() => {
    if (pipelines.length > 0 && selectedPipelineId === undefined) {
      // Look for a pipeline with "standard" in the name (case insensitive)
      const standardPipeline = pipelines.find(
        p => p.value.toLowerCase().includes('standard') || p.code?.toLowerCase().includes('standard')
      )
      if (standardPipeline) {
        setSelectedPipelineId(standardPipeline.id)
      }
    }
  }, [pipelines, selectedPipelineId])

  // Fetch pipeline stages for selected pipeline
  const { stages: pipelineStages, isLoading: stagesLoading } = usePipelineStages(accessToken, selectedPipelineId)

  // Update stages when pipeline stages change
  useEffect(() => {
    if (selectedPipelineId && pipelineStages.length > 0) {
      // Use pipeline-specific stages
      updateStages(pipelineStages)
    } else if (selectedPipelineId && pipelineStages.length === 0 && !stagesLoading) {
      // Clear stages when pipeline is selected but has no stages
      updateStages([])
    } else if (!selectedPipelineId) {
      // Use fixed stages when no pipeline is selected
      updateStages(FIXED_STAGES)
    }
  }, [selectedPipelineId, pipelineStages, stagesLoading, updateStages])

  useEffect(() => {
    let employeeFilter: string | undefined
    let employeeListFilter: string[] | undefined

    if (filterMode === 'my') {
      employeeFilter = employeeId
    } else if (filterMode === 'selected') {
      // Always pass the selectedEmployeeIds array, even if empty
      employeeListFilter = selectedEmployeeIds
    }
    // 'all' mode: no employee filtering

    fetchOpportunities(accessToken, employeeFilter, sourceApp, employeeListFilter, selectedPipelineId)
  }, [fetchOpportunities, employeeId, accessToken, filterMode, selectedEmployeeIds, selectedPipelineId, sourceApp])

  const sensors = useSensors(
    useSensor(PointerSensor, {
      activationConstraint: {
        distance: 8
      }
    })
  )

  const handleDragStart = (event: any) => {
    const { active } = event
    const opportunityId = active.id

    const draggedOpportunity = opportunities.find(item => item.id === opportunityId)

    setActiveOpportunity(draggedOpportunity || null)
  }

  const handleDragOver = (event: DragOverEvent) => {
    const { over, active } = event

    if (over) {
      const overId = over.id as string
      const activeId = active.id as string

      // Find the active opportunity
      const activeOpportunity = opportunities.find(op => op.id === activeId)

      // Check if we're hovering over a stage (column)
      const stage = stages.find(s => s.id === overId)
      if (stage) {
        setDragOverStage(overId as string)
        setDragOverOpportunity(null)
        setInsertPosition(null)
      } else {
        // We're hovering over another opportunity
        const overOpportunity = opportunities.find(op => op.id === overId)
        if (overOpportunity && activeOpportunity) {
          const overStageId = overOpportunity.salesPipelineStageRef
          const activeStageId = activeOpportunity.salesPipelineStageRef

          setDragOverStage(overStageId || null)

          // If dragging to a different column, enable insertion positioning
          if (activeStageId !== overStageId) {
            setDragOverOpportunity(overId)
            // For simplicity, we'll insert after the hovered card
            // You could enhance this to detect mouse position for before/after
            setInsertPosition('after')
          } else {
            // Same column - use existing sortable behavior
            setDragOverOpportunity(null)
            setInsertPosition(null)
          }
        } else {
          setDragOverStage(null)
          setDragOverOpportunity(null)
          setInsertPosition(null)
        }
      }
    } else {
      setDragOverStage(null)
      setDragOverOpportunity(null)
      setInsertPosition(null)
    }
  }

  const handleDragEnd = (event: DragEndEvent) => {
    const { active, over } = event

    // Clear all drag over states
    setDragOverStage(null)
    setDragOverOpportunity(null)
    setInsertPosition(null)
    setActiveOpportunity(null)

    if (!over || active.id === over.id) {
      return
    }

    const activeId = active.id as string
    const overId = over.id as string

    const activeOpportunity = opportunities.find(op => op.id === activeId)
    if (!activeOpportunity) return

    // Check if we're dropping on a stage (inter-column move to end)
    const targetStage = stages.find(s => s.id === overId)
    if (targetStage) {
      // Moving to a different stage at the end
      const activeStageId = activeOpportunity.salesPipelineStageRef
      if (activeStageId !== targetStage.id) {
        moveOpportunityToStage(activeId, targetStage.id, accessToken)
      }
      return
    }

    // Check if we're dropping on another opportunity
    const overOpportunity = opportunities.find(op => op.id === overId)
    if (overOpportunity) {
      const activeStageId = activeOpportunity.salesPipelineStageRef
      const overStageId = overOpportunity.salesPipelineStageRef

      if (activeStageId === overStageId) {
        // Reordering within the same column
        const stageOpportunities = opportunities.filter(op => {
          return op.salesPipelineStageRef === activeStageId
        })
        const activeIndex = stageOpportunities.findIndex(op => op.id === activeId)
        const overIndex = stageOpportunities.findIndex(op => op.id === overId)

        if (activeIndex !== overIndex) {
          const reorderedOpportunities = arrayMove(stageOpportunities, activeIndex, overIndex)
          if (activeStageId) {
            reorderOpportunities(activeStageId, reorderedOpportunities)
          }
        }
      } else {
        // Moving to a different stage with specific positioning
        const targetStageOpportunities = opportunities.filter(op => {
          return op.salesPipelineStageRef === overStageId
        })
        const insertIndex = targetStageOpportunities.findIndex(op => op.id === overId)

        // Insert after the target opportunity
        const newPosition = insertIndex + 1

        if (overStageId) {
          moveOpportunityToPosition(activeId, overStageId, newPosition, accessToken)
        }
      }
    }
  }

  if (isViewingOpportunity && selectedOpportunity) {
    return (
      <div className="gba:h-full gba:w-full" data-testid="opportunity-detail-container">
        <OpportunityRecord
