            </Button>
          </div>
        </Alert>
      </div>
    )
  }

  // Error state
  if (error) {
    return (
      <div className="gba:p-4" data-testid={`${DATA_TEST_ID_PREFIX}-error`}>
        <Alert variant="destructive">
          <div className="gba:flex gba:justify-between gba:items-center">
