            {opportunities.length === 0 && (!isDragging || !isDraggedOver) && (
              <div className="gba:text-center gba:py-4 gba:text-gray-500 gba:dark:text-gray-400">
                <Empty description="No opportunities" />
              </div>
            )}
          </div>
        </SortableContext>
      </div>
    </div>
  )
}

