          <div className="gba:text-sm gba:text-gray-500 gba:text-center">
            {total > 0 ? `${total} activit${total !== 1 ? 'ies' : 'y'} found` : 'No activities found'}
            {loading && <span> • Loading...</span>}
          </div>
        </div>
      </CardContent>
    </Card>
  )
