{"type":"text","file":{"filePath":"/tmp/every-agent-YFP3nb/repo/src/business-apps/crm/customers/apps/customer-relations/views/opportunity-view/opportunity-board/components/OpportunityCard.tsx","content":"import { useState, useRef, useEffect } from 'react'
import { formatCurrency, formatDateShort } from '../lib/utils'
import type { Opportunity } from '../lib/types'
import { useKanbanStore } from '../lib/kanban-store'
import { useSortable } from '@dnd-kit/sortable'
import { CSS } from '@dnd-kit/utilities'
import { generateAvatar } from '@/common/utils/avatar'
import { Button, Input, DatePicker } from 'antd'
import { EditOutlined, CheckOutlined, CloseOutlined } from '@ant-design/icons'
import type { Dayjs } from 'dayjs'
import dayjs from 'dayjs'

interface OpportunityCardProps {
  opportunity: Opportunity
  onSaveQuickEdit?: (id: string, fields: Partial<Opportunity>) => void
  isQuickEditing?: boolean
}

export function OpportunityCard({ opportunity, onSaveQuickEdit, isQuickEditing = false }: OpportunityCardProps) {
  const { selectedOpportunity, selectOpportunity } = useKanbanStore()
  const [quickEditMode, setQuickEditMode] = useState(false)
  const [editFields, setEditFields] = useState<Partial<Opportunity>>({})
  const [loading, setLoading] = useState(false)
  const cardRef = useRef<HTMLDivElement>(null)

  const {
    attributes,
    listeners,
    setNodeRef,
    transform,
    transition,
    isDragging
  } = useSortable({
    id: opportunity.id,
    data: {
      type: 'opportunity',
      opportunity
    }
  })

  const style = {
    transform: CSS.Transform.toString(transform),
    transition,
    opacity: isDragging ? 0.5 : 1,
    zIndex: isDragging ? 50 : 1
  }

  const handleClick = (e: React.MouseEvent) => {
    if (quickEditMode) return
    selectOpportunity(opportunity.id)
  }

  const handleQuickEditToggle = (e: React.MouseEvent) => {
    e.stopPropagation()
    if (!quickEditMode) {
      setEditFields({
        title: opportunity.title || opportunity.name,
        amount: opportunity.amount ?? opportunity.estimatedAmount,
        estimatedCloseDate: opportunity.estimatedCloseDate ?? opportunity.closeDate
      })
    }
    setQuickEditMode(prev => !prev)
  }

  const handleFieldChange = (field: keyof Opportunity, value: any) => {
    setEditFields(prev => ({ ...prev, [field]: value }))
  }

  const handleSave = async () => {
    setLoading(true)
    try {
      await useKanbanStore.getState().quickUpdateOpportunity(opportunity.id, editFields)
      setQuickEditMode(false)
      setEditFields({})
      if (onSaveQuickEdit) {
        onSaveQuickEdit(opportunity.id, editFields)
      }
    } finally {
      setLoading(false)
    }
  }

  const handleCancel = (e?: React.MouseEvent) => {
    e?.stopPropagation()
    setQuickEditMode(false)
    setEditFields({})
  }

  // Close quick edit on Escape key
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'Escape' && quickEditMode) {
        handleCancel()
      }
    }
    window.addEventListener('keydown', handleKeyDown)
    return () => window.removeEventListener('keydown', handleKeyDown)
  }, [quickEditMode])

  // Click outside to cancel quick edit
  useEffect(() => {
    const handleClickOutside = (e: MouseEvent) => {
      if (cardRef.current && !cardRef.current.contains(e.target as Node) && quickEditMode) {
        handleCancel()
      }
    }
    if (quickEditMode) {
      document.addEventListener('mousedown', handleClickOutside)
      return () => document.removeEventListener('mousedown', handleClickOutside)
    }
  }, [quickEditMode])

  const isSelected = selectedOpportunity?.id === opportunity.id

  const QuickEditTrigger = isQuickEditing ? (
    <button
      onClick={handleQuickEditToggle}
      className="gba:opacity-0 gba:group-hover:opacity-100 gba:transition-opacity gba:duration-200 gba:absolute gba:top-2 gba:right-2 gba:p-1 gba:rounded gba:bg-gray-100 gba:hover:bg-blue-100 gba:text-gray-500 gba:hover:text-blue-600 gba:dark:bg-gray-700 gba:dark:hover:bg-blue-900 gba:dark:text-gray-400 gba:z-20"
      title="Quick Edit"
      data-testid="quick-edit-trigger"
    >
      {quickEditMode ? (
        <CloseOutlined className="gba:w-3.5 gba:h-3.5" />
      ) : (
        <EditOutlined className="gba:w-3.5 gba:h-3.5" />
      )}
    </button>
  ) : null

  const QuickEditOverlay = quickEditMode ? (
    <div className="gba:fixed gba:inset-0 gba:bg-black/10 gba:z-40" />
  ) : null

  const QuickEditForm = quickEditMode ? (
    <div className="gba:absolute gba:inset-0 gba:bg-white gba:dark:bg-gray-800 gba:z-50 gba:rounded gba:p-3 gba:shadow-lg gba:border gba:border-blue-200 gba:dark:border-blue-700">
      <div className="gba:space-y-2">
        <div>
          <label className="gba:block gba:text-xs gba:font-medium gba:mb-0.5 gba:text-gray-600 gba:dark:text-gray-400">
            Title
          </label>
          <Input
            size="small"
            value={editFields.title || ''}
            onChange={e => handleFieldChange('title', e.target.value)}
            onClick={e => e.stopPropagation()}
            placeholder="Opportunity title"
            className="gba:text-sm"
            autoFocus
          />
        </div>
        <div>
          <label className="gba:block gba:text-xs gba:font-medium gba:mb-0.5 gba:text-gray-600 gba:dark:text-gray-400">
            Amount
          </label>
          <Input
            size="small"
            type="number"
            value={editFields.amount || ''}
            onChange={e => handleFieldChange('amount', Number(e.target.value))}
            onClick={e => e.stopPropagation()}
            placeholder="Amount"
            prefix="$"
            className="gba:text-sm"
          />
        </div>
        <div>
          <label className="gba:block gba:text-xs gba:font-medium gba:mb-0.5 gba:text-gray-600 gba:dark:text-gray-400">
            Close Date
          </label>
          <DatePicker
            size="small"
            value={editFields.estimatedCloseDate ? dayjs(editFields.estimatedCloseDate) : null}
            onChange={(date: Dayjs | null) => handleFieldChange('estimatedCloseDate', date?.toISOString())}
            onClick={e => e.stopPropagation()}
            placeholder="Select date"
            className="gba:w-full gba:text-sm"
          />
        </div>
        <div className="gba:flex gba:gap-2 gba:pt-1">
          <Button
            size="small"
            type="primary"
            icon={<CheckOutlined />}
            onClick={e => { e.stopPropagation(); handleSave() }}
            loading={loading}
            className="gba:flex-1"
          >
            Save
          </Button>
          <Button
            size="small"
            icon={<CloseOutlined />}
            onClick={e => { e.stopPropagation(); handleCancel(e) }}
            className="gba:flex-1"
          >
            Cancel
          </Button>
        </div>
      </div>
    </div>
  ) : null

  return (
    <div
      ref={(node) => {
        setNodeRef(node)
        if (cardRef) {
          (cardRef as any).current = node
        }
      }}
      style={style}
      {...attributes}
      {...listeners}
      onClick={handleClick}
      className={`gba:group gba:cursor-pointer gba:bg-white gba:dark:bg-gray-800 gba:p-3 gba:rounded-lg gba:shadow-sm gba:border gba:transition-all gba:duration-200 gba:relative ${
        isSelected
          ? 'gba:border-blue-500 gba:ring-2 gba:ring-blue-200 gba:dark:ring-blue-800 gba:shadow-md'
          : 'gba:border-gray-100 gba:dark:border-gray-700 hover:gba:border-gray-200 gba:dark:hover:border-gray-600 hover:gba:shadow-md'
      }`}
    >
      {QuickEditTrigger}

      {/* Quick Edit Form Overlay */}
      {quickEditMode && QuickEditOverlay}
      {quickEditMode && QuickEditForm}

      {/* Normal View */}
      {!quickEditMode && (
        <>
          <div className="gba:flex gba:items-start gba:justify-between gba:mb-1">
            <h4 className="gba:text-sm gba:font-medium gba:text-gray-900 gba:dark:text-white gba:leading-tight gba:pr-6">
              {opportunity.title || opportunity.name}
            </h4>
          </div>

          <div className="gba:flex gba:items-center gba:gap-2 gba:mt-2">
            {opportunity.owner && (
              <div className="gba:w-5 gba:h-5 gba:rounded-full gba:flex gba:items-center gba:justify-center gba:text-xs gba:font-medium gba:text-white gba:overflow-hidden gba:flex-shrink-0 gba:shadow-sm">
                <img
                  src={generateAvatar(opportunity.owner)}
                  alt={opportunity.owner}
                  className="gba:w-full gba:h-full gba:object-cover"
                  onError={e => {
                    const target = e.target as HTMLImageElement
                    target.style.display = 'none'
                    target.parentElement!.textContent = opportunity.owner?.charAt(0).toUpperCase() || '?'
                  }}
                />
              </div>
            )}
            <div className="gba:flex gba:items-center gba:gap-1 gba:text-xs gba:text-gray-500 gba:dark:text-gray-400">
              <span>{opportunity.owner}</span>
              {opportunity.account && (
                <>
                  <span className="gba:text-gray-300 gba:dark:text-gray-600">·</span>
                  <span className="gba:truncate gba:max-w-[100px]">{opportunity.account}</span>
                </>
              )}
            </div>
          </div>

          <div className="gba:flex gba:items-center gba:justify-between gba:mt-2">
            <div className="gba:text-sm gba:font-medium gba:text-gray-900 gba:dark:text-white">
              {formatCurrency(opportunity.amount ?? opportunity.estimatedAmount)}
            </div>
            {(opportunity.estimatedCloseDate ?? opportunity.closeDate) && (
              <div className="gba:text-xs gba:text-gray-400 gba:dark:text-gray-500">
                {formatDateShort(opportunity.estimatedCloseDate ?? opportunity.closeDate)}
              </div>
            )}
          </div>
        </>
      )}
    </div>
  )
}

export default OpportunityCard","numLines":278,"startLine":1,"totalLines":278}}

{"type":"text","file":{"filePath":"/tmp/every-agent-YFP3nb/repo/src/business-apps/crm/customers/apps/customer-relations/views/opportunity-view/opportunity-board/lib/kanban-store.ts","content":"import { create } from 'zustand'
import { Stage, Opportunity } from './types'
import { FIXED_STAGES } from './stages'
import { GET_OPPORTUNITIES } from '../queries/kanbanQueries'
import { graphQLClient } from '@/common/network/graphql/GraphQLClient'
import { opportunityClient } from '@/common/network/opportunity/OpportunityClient'
import { enforceQueryLimit } from '@/business-apps/crm/common/utils/queryLimits'

interface KanbanStore {
  stages: Stage[]
  opportunities: Opportunity[]
  loading: boolean
  error: Error | null
  isEditingOpportunity: boolean
  editingOpportunityId: string | null
  selectedOpportunity: Opportunity | null
  isViewingOpportunity: boolean

  fetchOpportunities: (
    accessToken: string,
    employeeId?: string,
    sourceApp?: string,
    selectedEmployeeIds?: string[],
    selectedPipelineId?: string
  ) => Promise<Opportunity[]>
  updateStages: (stages: Stage[]) => void
  moveOpportunity: (opportunityId: string, targetStageId: string, accessToken: string) => Promise<void>
  moveOpportunityToStage: (opportunityId: string, targetStageId: string, accessToken: string) => Promise<void>
  moveOpportunityToPosition: (
    opportunityId: string,
    targetStageId: string,
    position: number,
    accessToken: string
  ) => Promise<void>
  reorderOpportunities: (stageId: string, reorderedOpportunities: Opportunity[]) => void
  updateOpportunity: (opportunityId: string, updates: Partial<Opportunity>, accessToken: string) => Promise<void>
  quickUpdateOpportunity: (opportunityId: string, updates: Partial<Opportunity>) => Promise<void>
  deleteOpportunity: (opportunityId: string, accessToken: string) => Promise<void>
  setEditingOpportunity: (opportunityId: string | null) => void
  selectOpportunity: (opportunityId: string | null) => void
}

export const useKanbanStore = create<KanbanStore>((set, get) => ({
  stages: FIXED_STAGES,
  opportunities: [],
  loading: false,
  error: null,
  isEditingOpportunity: false,
  editingOpportunityId: null,
  selectedOpportunity: null,
  isViewingOpportunity: false,

  updateStages: (stages: Stage[]) => {
    set({ stages })
  },

  fetchOpportunities: async (
    accessToken: string,
    employeeId?: string,
    sourceApp?: string,
    selectedEmployeeIds?: string[],
    selectedPipelineId?: string
  ) => {
    set({ loading: true, error: null })
    try {
      graphQLClient.setAccessToken(accessToken)

      // Build where conditions
      const where: any = { isDeleted: { _eq: false } }

      // Add sourceApp filtering if provided
      if (sourceApp) {
        where.sourceApp = { _eq: sourceApp }
      }

      // Add pipeline filtering if provided
      if (selectedPipelineId) {
        where.salesPipelineRef = { _eq: selectedPipelineId }
      }

      // Handle employee filtering logic
      if (selectedEmployeeIds !== undefined) {
        if (selectedEmployeeIds.length > 0) {
          // If specific employees are selected, filter by those
          where.ownerEmployeeId = { _in: selectedEmployeeIds }
        } else {
          // If in "selected employees" mode but none selected, show no results
          where.ownerEmployeeId = { _in: [] }
        }
      } else if (employeeId) {
        // Fallback to single employee filter (for "My Opportunities")
        where.ownerEmployeeId = { _eq: employeeId }
      }
      // If no employee filtering is specified, show all opportunities

      const response = await graphQLClient.request(GET_OPPORTUNITIES, {
        offset: 0,
        limit: enforceQueryLimit(200), // Enforce the 100 item limit instead of 200
        where
      })

      if (!response || !response.Opportunity) {
        set({ error: new Error('Invalid response format from server'), loading: false })
        return []
      }

      const opportunities = response.Opportunity.map((opp: any, index: number) => ({
        ...opp,
        id: opp.id || '',
        title: opp.name || '',
        stageId: opp.salesPipelineStageRef || FIXED_STAGES[0].id,
        salesPipelineRef: opp.salesPipelineRef,
        salesPipelineStageRef: opp.salesPipelineStageRef,
        version: opp.version || 0,
        owner: opp.ownerEmployee?.fullName || 'Unassigned',
        account: opp.account?.name || '',
        amount: opp.estimatedAmount || 0,
        position: opp.position || index // Add position for ordering
      }))

      set({ opportunities, loading: false })
      return opportunities
    } catch (error) {
      set({ error: error as Error, loading: false })
      return []
    }
  },

  moveOpportunity: async (opportunityId: string, targetStageId: string, accessToken: string) => {
    const opportunity = get().opportunities.find(opp => opp.id === opportunityId)
    if (!opportunity) return

    const originalStageId = opportunity.stageId
    const originalSalesPipelineStageRef = opportunity.salesPipelineStageRef

    set(state => ({
      opportunities: state.opportunities.map(opp =>
        opp.id === opportunityId
          ? {
              ...opp,
              stageId: targetStageId,
              salesPipelineStageRef: targetStageId, // Update both fields
              version: opp.version + 1
            }
          : opp
      )
    }))

    opportunityClient
      .updateOpportunityStage(opportunityId, targetStageId, opportunity.version, opportunity, accessToken)
      .catch(error => {
        set(state => ({
          opportunities: state.opportunities.map(opp =>
            opp.id === opportunityId
              ? {
                  ...opp,
                  stageId: originalStageId,
                  salesPipelineStageRef: originalSalesPipelineStageRef,
                  version: opportunity.version
                }
              : opp
          ),
          error: error as Error
        }))
      })
  },

  moveOpportunityToStage: async (opportunityId: string, targetStageId: string, accessToken: string) => {
    const opportunity = get().opportunities.find(opp => opp.id === opportunityId)
    if (!opportunity) return

    const originalStageId = opportunity.stageId
    const originalSalesPipelineStageRef = opportunity.salesPipelineStageRef

    // Get the target stage opportunities to determine position (add to end)
    const targetStageOpportunities = get().opportunities.filter(op => {
      return op.salesPipelineStageRef === targetStageId
    })
    const newPosition = targetStageOpportunities.length

    // Optimistic update - move the card to end of target stage
    set(state => ({
      opportunities: state.opportunities.map(opp =>
        opp.id === opportunityId
          ? {
              ...opp,
              stageId: targetStageId,
              salesPipelineStageRef: targetStageId, // Update both fields
              position: newPosition,
              version: opp.version + 1
            }
          : opp
      )
    }))

    // Make API call in background
    opportunityClient
      .updateOpportunityStage(opportunityId, targetStageId, opportunity.version, opportunity, accessToken)
      .catch(error => {
        // Revert on error
        set(state => ({
          opportunities: state.opportunities.map(opp =>
            opp.id === opportunityId
              ? {
                  ...opp,
                  stageId: originalStageId,
                  salesPipelineStageRef: originalSalesPipelineStageRef,
                  position: opportunity.position,
                  version: opportunity.version
                }
              : opp
          ),
          error: error as Error
        }))
      })
  },

  moveOpportunityToPosition: async (
    opportunityId: string,
    targetStageId: string,
    position: number,
    accessToken: string
  ) => {
    const opportunity = get().opportunities.find(opp => opp.id === opportunityId)
    if (!opportunity) return

    const originalStageId = opportunity.stageId
    const originalSalesPipelineStageRef = opportunity.salesPipelineStageRef
    const originalPosition = opportunity.position

    // Get target stage opportunities and insert at specific position
    const targetStageOpportunities = get()
      .opportunities.filter(op => {
        return op.salesPipelineStageRef === targetStageId && op.id !== opportunityId
      })
      .sort((a, b) => (a.position || 0) - (b.position || 0))

    // Insert the opportunity at the specified position
    targetStageOpportunities.splice(position, 0, {
      ...opportunity,
      stageId: targetStageId,
      salesPipelineStageRef: targetStageId
    })

    // Update positions for all opportunities in target stage
    const updatedTargetOpportunities = targetStageOpportunities.map((op, index) => ({
      ...op,
      position: index,
      stageId: targetStageId,
      salesPipelineStageRef: targetStageId
    }))

    // Optimistic update
    set(state => {
      const otherOpportunities = state.opportunities.filter(op => {
        return op.salesPipelineStageRef !== targetStageId && op.id !== opportunityId
      })

      return {
        opportunities: [
          ...otherOpportunities,
          ...updatedTargetOpportunities.map(op => (op.id === opportunityId ? { ...op, version: op.version + 1 } : op))
        ]
      }
    })

    // Make API call in background
    opportunityClient
      .updateOpportunityStage(opportunityId, targetStageId, opportunity.version, opportunity, accessToken)
      .catch(error => {
        // Revert on error
        set(state => ({
          opportunities: state.opportunities.map(opp =>
            opp.id === opportunityId
              ? {
                  ...opp,
                  stageId: originalStageId,
                  salesPipelineStageRef: originalSalesPipelineStageRef,
                  position: originalPosition,
                  version: opportunity.version
                }
              : opp
          ),
          error: error as Error
        }))
      })
  },

  reorderOpportunities: (stageId: string, reorderedOpportunities: Opportunity[]) => {
    set(state => {
      // Update positions for the reordered opportunities
      const updatedReorderedOps = reorderedOpportunities.map((op, index) => ({
        ...op,
        position: index
      }))

      // Update the opportunities array with the new positions
      const updatedOpportunities = state.opportunities.map(opp => {
        if (opp.salesPipelineStageRef === stageId) {
          const reorderedOp = updatedReorderedOps.find(rop => rop.id === opp.id)
          return reorderedOp || opp
        }
        return opp
      })

      // Sort opportunities by position within each stage
      const sortedOpportunities = updatedOpportunities.sort((a, b) => {
        if (a.salesPipelineStageRef === b.salesPipelineStageRef) {
          return (a.position || 0) - (b.position || 0)
        }
        return 0
      })

      return { opportunities: sortedOpportunities }
    })
  },

  updateOpportunity: async (opportunityId: string, updates: Partial<Opportunity>, _accessToken: string) => {
    set(state => ({
      opportunities: state.opportunities.map(opp => (opp.id === opportunityId ? { ...opp, ...updates } : opp)),
      isEditingOpportunity: false,
      editingOpportunityId: null
    }))
    return Promise.resolve()
  },

  quickUpdateOpportunity: async (opportunityId: string, updates: Partial<Opportunity>) => {
    set(state => ({
      opportunities: state.opportunities.map(opp => {
        if (opp.id !== opportunityId) return opp
        // Normalize quick-edit fields to canonical properties
        const normalized: Partial<Opportunity> = { ...updates }
        if (updates.title !== undefined) {
          normalized.name = updates.title
        }
        if (updates.amount !== undefined) {
          normalized.estimatedAmount = updates.amount
        }
        if (updates.estimatedCloseDate !== undefined) {
          normalized.closeDate = updates.estimatedCloseDate
        }
        return { ...opp, ...normalized }
      }),
      selectedOpportunity:
        state.selectedOpportunity?.id === opportunityId
          ? { ...state.selectedOpportunity, ...updates }
          : state.selectedOpportunity
    }))
    return Promise.resolve()
  },

  deleteOpportunity: async (opportunityId: string, _accessToken: string) => {
    set(state => ({
      opportunities: state.opportunities.filter(opp => opp.id !== opportunityId)
    }))
    return Promise.resolve()
  },

  setEditingOpportunity: (opportunityId: string | null) => {
    set({
      editingOpportunityId: opportunityId,
      isEditingOpportunity: opportunityId !== null
    })
  },

  selectOpportunity: (opportunityId: string | null) => {
    if (opportunityId === null) {
      set({
        selectedOpportunity: null,
        isViewingOpportunity: false
      })
      return
    }

    const opportunity = get().opportunities.find(opp => opp.id === opportunityId)

    set({
      selectedOpportunity: opportunity || null,
      isViewingOpportunity: opportunity !== undefined
    })
  }
